  "001_initial.sql": "-- Users (populated from Google OAuth on first login)\nCREATE TABLE IF NOT EXISTS users (\n  id TEXT PRIMARY KEY,\n  email TEXT UNIQUE NOT NULL,\n  name TEXT NOT NULL,\n  picture TEXT,\n  role TEXT NOT NULL DEFAULT 'member',\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\n-- Projects\nCREATE TABLE IF NOT EXISTS projects (\n  id TEXT PRIMARY KEY,\n  name TEXT NOT NULL,\n  slug TEXT UNIQUE NOT NULL,\n  description TEXT,\n  status TEXT NOT NULL DEFAULT 'active',\n  created_by TEXT NOT NULL REFERENCES users(id),\n  github_repo_url TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\n-- Project membership\nCREATE TABLE IF NOT EXISTS project_members (\n  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,\n  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  role TEXT NOT NULL DEFAULT 'member',\n  added_at TEXT NOT NULL DEFAULT (datetime('now')),\n  PRIMARY KEY (project_id, user_id)\n);\n\n-- SDLC Phases per project\nCREATE TABLE IF NOT EXISTS project_phases (\n  id TEXT PRIMARY KEY,\n  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,\n  name TEXT NOT NULL,\n  display_order INTEGER NOT NULL,\n  status TEXT NOT NULL DEFAULT 'not-started',\n  started_at TEXT,\n  completed_at TEXT\n);\n\n-- Documents attached to phases\nCREATE TABLE IF NOT EXISTS documents (\n  id TEXT PRIMARY KEY,\n  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,\n  phase_id TEXT REFERENCES project_phases(id),\n  title TEXT NOT NULL,\n  filename TEXT NOT NULL,\n  category TEXT NOT NULL,\n  file_path TEXT NOT NULL,\n  generated_by TEXT,\n  requires_review INTEGER DEFAULT 0,\n  confidence REAL,\n  created_by TEXT REFERENCES users(id),\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\n-- Indexes\nCREATE INDEX IF NOT EXISTS idx_projects_created_by ON projects(created_by);\nCREATE INDEX IF NOT EXISTS idx_projects_status ON projects(status);\nCREATE INDEX IF NOT EXISTS idx_project_members_user ON project_members(user_id);\nCREATE INDEX IF NOT EXISTS idx_project_phases_project ON project_phases(project_id);\nCREATE INDEX IF NOT EXISTS idx_documents_project ON documents(project_id);\nCREATE INDEX IF NOT EXISTS idx_documents_phase ON documents(phase_id);\n",
